<script setup>
import { formatSize } from '@/utils/util'
import { uploadFile } from '@/services/knowledge'
import useToastService from '@/hooks/useToastService'
import { i18nRender } from '@/locales'
import { getFileType, fileIconRender } from '../FileIcon'

const toast = useToastService()
const props = defineProps({
  id: {
    type: String,
    default: ''
  },
  showButton: {
    type: Boolean,
    default: false
  }
})

const files = ref([])

const onRemoveTemplatingFile = (file, removeFileCallback, index) => {
  removeFileCallback(index)
}

const onClearTemplatingUpload = (clear) => {
  files.value = []
  clear()
}

function handleFileRemove(event) {
  files.value = event.files
}

const onSelectedFiles = (event) => {
  files.value = event.files
}

const emits = defineEmits(['hide', 'success'])
const loading = ref(false)
const uploadEvent = () => {
  console.log('upload', files.value)
  const formData = new FormData()
  formData.append('id', props.id)
  files.value.forEach((file) => {
    formData.append('files', file)
  })
  loading.value = true
  uploadFile(formData)
    .then(() => {
      toast.add({ severity: 'success', summary: i18nRender('kb.success'), detail: i18nRender('kb.importSuccess'), life: 3000 })
      emits('success')
    })
    .finally(() => {
      loading.value = false
    })
}

function close() {
  emits('hide')
}

function getSelectedFiles() {
  return new Promise((resolve) => {
    resolve(files.value)
  })
}

function iconRender(fileName) {
  const type = getFileType(fileName)
  return fileIconRender(type)
}

defineExpose({
  getSelectedFiles
})
</script>
<template>
  <div class="uploader-container">
    <FileUpload
      name="uploader"
      url=""
      :multiple="true"
      accept=".pdf,.doc,.docx,.txt,.html,.htm,.md,.json,.jsonl,.epub,.mobi,.xml,.pptx"
      :fileLimit="200"
      :maxFileSize="500 * 1024 * 1024"
      @remove="handleFileRemove"
      @select="onSelectedFiles"
    >
      <template #header="{ chooseCallback, clearCallback, files }">
        <div class="flex flex-wrap justify-between items-center flex-1 gap-2">
          <div class="flex gap-2">
            <Button @click="chooseCallback()" icon="pi pi-plus" :label="$t('kb.selectFile')"></Button>
            <Button
              @click="onClearTemplatingUpload(clearCallback)"
              icon="pi pi-times"
              :label="$t('kb.clearAll')"
              severity="danger"
              :disabled="!files || files.length === 0"
            ></Button>
          </div>
        </div>
      </template>
      <template #content="{ files, removeFileCallback }">
        <div v-if="files.length > 0" class="max-h-[300px] overflow-auto">
          <div class="flex flex-wrap p-0 gap-3">
            <div
              v-for="(file, index) of files"
              :key="file.name + file.type + file.size"
              class="m-0 px-3 w-full flex justify-between border border-solid border-slate-300 rounded items-center gap-3"
            >
              <div class="flex flex-wrap gap-3 items-center">
                <!-- <i class="pi pi-file-pdf text-4xl"></i> -->
                <img :src="iconRender(file.name)" alt="" style="width: 35px" />
                <div>
                  <div class="font-semibold file-title" v-tooltip="file.name">{{ file.name }}</div>
                  <div>{{ formatSize(file.size) }}</div>
                </div>
              </div>
              <Button icon="pi pi-times" @click="onRemoveTemplatingFile(file, removeFileCallback, index)" rounded text severity="danger" />
            </div>
          </div>
        </div>
      </template>
      <template #empty>
        <div class="flex items-center content-center flex-col border border-dashed p-2">
          <i class="pi pi-cloud-upload border border-solid border-slate-300 text-slate-300 rounded-full p-5 text-8xl" />
          <p class="mt-4 mb-0 text-center">{{ $t('kb.uploadFileTip1') }}<br />{{ $t('kb.uploadFileTip2') }}</p>
        </div>
      </template>
    </FileUpload>

    <div class="flex items-center justify-end space-x-4 mt-4" v-if="showButton">
      <Button :label="$t('lang.cancel')" severity="secondary" @click="close"></Button>
      <Button :label="$t('kb.import')" @click="uploadEvent" :disabled="files.length === 0 || loading"></Button>
    </div>
  </div>
</template>
<style scoped lang="scss">
.uploader-container {
  ::v-deep(.p-fileupload-buttonbar),
  ::v-deep(.p-fileupload-content) {
    @apply border-0;
  }
}
.file-title {
  overflow: hidden;
  white-space: nowrap;
  word-break: break-all;
  text-overflow: ellipsis;
  max-width: 200px;
}
</style>
